function createCandidateAcquisition(selected, blocklists = generationBlocklists(selected)) {
  const coverage = acquisitionCoverage(selected, blocklists);
  return { selected, blocklists, searched: new Set(), cachedQueries: new Set(), before: coverage.artists, cachedPages: 0 };
}

functions.reuseQualifyingCache:
function reuseQualifyingCache(cachedRows, acquisition) {
  const existing = loadCandidatePool(), existingIds = new Set(existing.map(row => row.track.id));
  const before = acquisitionCoverage(acquisition.selected, acquisition.blocklists);
  const additions = [...cachedRows.values()].filter(row => !existingIds.has(row.track.id));
  if (!additions.length) return;
  const prospective = [...existing, ...additions];
  const ctx = acquisitionContext(acquisition.selected, prospective);
  const { eligible } = eligibleGroupCandidates(acquisition.selected, acquisition.blocklists, ctx, prospective);
  const counts = new Map([...before.byArtist].map(([artist, signatures]) => [artist, new Set(signatures)]));
  let slots = CANDIDATE_POOL_MAX_ITEMS;
  const chosen = [];
  for (const item of eligible.filter(item => !existingIds.has(item.track.id) && acquisitionQualifying(item)).sort((a, b) => b.groupBase - a.groupBase)) {
    if (!slots) break;
    const artists = [...trackArtistKeys(item.track)], signature = trackSignature(item.track);
    if (!artists.length || artists.some(artist => (counts.get(artist)?.size || 0) >= 2 || counts.get(artist)?.has(signature))) continue;
    chosen.push(cachedRows.get(item.track.id)); slots--;
    for (const artist of artists) {
      if (!counts.has(artist)) counts.set(artist, new Set());
      counts.get(artist).add(signature);
    }
  }
  if (!chosen.length) { rebuildCanonicalCleanVariantSignatures(existing); return; }
  // D.2 owns retention across all saved profiles, including redundant qualified rows.
  saveCandidatePool([...existing, ...chosen]);
  rebuildCanonicalCleanVariantSignatures(loadCandidatePool());
  renderHistorySummary();
}

