async function primeDiverseQueries(token, rows, maxNewSearches, acquisition, onSearched = () => {}) {
  const unique = [...new Map(rows.map(row => [canonicalQuery(row.query), row])).values()];
  const feedback = feedbackArtistStats();
  const allowed = unique.filter(row => {
    const artist = normalizeArtistName(extractQuotedQueryValue(row.query, 'artist'));
    return !artist || (!acquisition.blocklists.explicitBlockedNames.has(artist) &&
      !acquisition.blocklists.feedbackBlockedNames.has(artist) && !acquisition.blocklists.historyBlockedNames.has(artist) &&
      artistFeedbackScore(feedback.get(artist)) > ARTIST_FEEDBACK_EXCLUSION_SCORE);
  });
  // Read all already-paid pages before spending any new request. Reuse once per generation.
  const cachedRows = new Map();
  for (const row of allowed) {
    const key = canonicalQuery(row.query);
    if (acquisition.cachedQueries.has(key)) continue;
    acquisition.cachedQueries.add(key);
    const tracks = new Map(), acquiredTimes = new Map();
    for (let offset = 0; offset <= 90; offset += 10) {
      const page = readSearchCache(row.query, offset);
      if (page === null) continue;
      acquisition.cachedPages++;
      let acquiredAt = Date.now();
      try { acquiredAt = JSON.parse(localStorage.getItem(searchCacheKey(row.query, offset))).savedAt; } catch {}
      for (const track of page) if (queryMatchesTrack(row.query, track) && acquiredAt >= (acquiredTimes.get(track.id) || 0)) { tracks.set(track.id, track); acquiredTimes.set(track.id, acquiredAt); }
    }
    if (tracks.size) {
      queriesAttemptedThisGeneration.add(key);
      for (const track of tracks.values()) {
        const current = cachedRows.get(track.id) || { track: slimTrack(track), queries: [], savedAt: acquiredTimes.get(track.id), lastUsedAt: Date.now() };
        if (acquiredTimes.get(track.id) > current.savedAt) { current.savedAt = acquiredTimes.get(track.id); current.track = slimTrack(track); }
        current.queries = [...new Set([...current.queries, row.query])];
        cachedRows.set(track.id, current);
      }
    }
  }
  if (cachedRows.size) reuseQualifyingCache(cachedRows, acquisition);
  const before = newSearchesThisGeneration;
  const pending = [...allowed];
  while (pending.length && newSearchesThisGeneration - before < maxNewSearches && newSearchesThisGeneration < maxNewSearchesThisGeneration) {
    const coverage = acquisitionCoverage(acquisition.selected, acquisition.blocklists);
    const capacity = row => coverage.queryCapacity.get(canonicalQuery(row.query)) || 0;
    const ranked = pending.map((row, order) => ({ row, order, capacity: capacity(row) })).sort((a, b) => a.capacity - b.capacity || a.order - b.order);
    const chosen = ranked.find(({ row }) => {
      const key = canonicalQuery(row.query), artist = normalizeArtistName(extractQuotedQueryValue(row.query, 'artist'));
      return !acquisition.searched.has(key) && (!artist || (coverage.byArtist.get(artist)?.size || 0) < 2) &&
        searchOffsetsForQuery(row.query).some(offset => !hasFreshSearchCache(row.query, offset));
    });
    if (!chosen) break;
    pending.splice(pending.indexOf(chosen.row), 1);
    const row = chosen.row;
    const offset = searchOffsetsForQuery(row.query).find(offset => !hasFreshSearchCache(row.query, offset));
    acquisition.searched.add(canonicalQuery(row.query));
    await searchTracks(token, row.query, offset);
    onSearched(row);
  }
}

functions.generateOfficePlaylist:
async function generateOfficePlaylist() {
  try {
    generateButton.disabled = true;
    newSearchesThisGeneration = 0;
    queriesAttemptedThisGeneration = new Set();
    playlistBox.style.display = "none";
    playlistResult.textContent = "";
    progressBox.textContent = "Przygotowuję profile...";

    const token = await getValidAccessToken();
    if (!token) throw new Error("Brak aktywnej sesji Spotify.");

    const total = Number(playlistLength.value);
    maxNewSearchesThisGeneration = searchBudgetForTarget(total);

    progressBox.textContent = "Sprzątam playlisty Office Music Mixer starsze niż 72 godziny...";
    const playlistCleanupResult = await cleanupOldOfficePlaylists(token);

    const selected = selectedProfiles();
    const bartek = selected.find(profile => profile.id === "bartek");
    if (!bartek) {
      throw new Error("Profil Bartka musi być aktywny. Jest głównym profilem tej aplikacji.");
    }
    if (!hasMusicProfile(bartek)) {
      throw new Error("Profil Bartka nie ma danych muzycznych. Wypełnij ankietę gustu lub dodaj gatunki/artystów wzorcowych.");
    }

    const mixProfiles = selected.filter(hasMusicProfile);
    const ignoredProfiles = selected.filter(profile => !hasMusicProfile(profile));

    progressBox.textContent = "Sprawdzam świeżość Last.fm (historia 10 min, baza tagów 60 min)...";
    await refreshLastFmBeforeGeneration(mixProfiles, total);

    progressBox.textContent = "Synchronizuję historię odtworzeń...";
    await syncSpotifyRecentHistory(token);
    const acquisitionBlocklists = generationBlocklists(selected);
    const acquisition = createCandidateAcquisition(mixProfiles, acquisitionBlocklists);

    progressBox.textContent =
      `Odświeżam artystów wzorcowych (budżet ${maxNewSearchesThisGeneration} nowych wyszukiwań)...`;
    await primeManualSeedArtists(token, mixProfiles, 3, acquisition);

    const genrePrimeBudget = genrePrimeBudgetForTarget(total);
    progressBox.textContent =
      `Rozszerzam słabo reprezentowane gatunki (do ${genrePrimeBudget} nowych wyszukiwań)...`;
    await primeProfileGenres(token, mixProfiles, genrePrimeBudget, acquisition);

    const remainingSearchBudget = Math.max(0, maxNewSearchesThisGeneration - newSearchesThisGeneration);
    progressBox.textContent = "Szukam wspólnego mianownika i różnych kwalifikowalnych wykonawców...";
    await primeCommonGroupQueries(token, mixProfiles, Math.min(3, remainingSearchBudget), acquisition);

    progressBox.textContent = "Buduję model grupowy: satysfakcja, fairness, xQuAD i MMR...";
    const blocklists = generationBlocklists(selected);
    const ctx = buildGroupRecommendationContext(mixProfiles, loadCandidatePool(), createLastFmEvidenceSnapshot());
    const { eligible, stats } = eligibleGroupCandidates(mixProfiles, blocklists, ctx);

    if (!eligible.length) {
      throw new Error("Po filtrach nie został żaden kandydat. Diagnostyka będzie wymagała poluzowania źródeł lub filtrów.");
    }

    const groupResult = selectGroupPlaylist(eligible, total, ctx, stats);
    groupResult.acquisition = { before: acquisition.before, after: acquisitionCoverage(mixProfiles, blocklists).artists, cachedPages: acquisition.cachedPages, newSearches: newSearchesThisGeneration };
    const finalTracks = sequencePlaylistForListening(groupResult.tracks, 5);
    groupResult.tracks = finalTracks;

    if (!finalTracks.length) {
      throw new Error("Algorytm grupowy nie wybrał żadnego utworu.");
    }

    progressBox.textContent =
      `Tworzę playlistę i zapisuję ${finalTracks.length} utworów...`;

    const playlist = await createPlaylist(token, selected, finalTracks.length);
    await addItemsToPlaylist(
      token,
      playlist.id,
      finalTracks.map(track => track.uri)
    );

    recordSeedArtistSelections(finalTracks, selected);
    // Both Spotify writes have completed. Read fresh evidence again so feedback
    // or history changed while awaiting the API is reflected in diagnostics.
    const diagnosticEvidence = createLastFmEvidenceSnapshot();
    const diagnostics = buildPlaylistDiagnostics(finalTracks, selected, groupResult, diagnosticEvidence);
    saveRecentPlaylistSnapshot(playlist, finalTracks, selected, total, groupResult, diagnosticEvidence, diagnostics);
    renderPlaylistResult(
      playlist,
      finalTracks,
      selected,
      ignoredProfiles,
      total,
      playlistCleanupResult,
      groupResult,
      diagnosticEvidence,
      diagnostics
    );

    // Pula Spotify jest kosztowna do odbudowy, więc po udanym generowaniu zapisujemy
    // jej skompaktowaną wersję do D1 razem z trwałymi preferencjami. Błąd chmury
    // nie może unieważnić poprawnie utworzonej playlisty.
    try {
      await uploadCloudStateIfChanged(token, { status: true });
    } catch (cloudErr) {
      console.error("Cloud sync after generation:", cloudErr);
      setCloudStatus(`po generowaniu: ${cloudErr.message}`, "error");
    }
    progressBox.textContent = "";

  } catch (err) {
    console.error(err);
    playlistResult.textContent = err.message;
    playlistBox.style.display = "block";
    progressBox.textContent = "";
  } finally {
    generateButton.disabled = false;
  }
}

functions.searchTracks:
async function searchTracks(token, query, offset = 0) {
  queriesAttemptedThisGeneration.add(canonicalQuery(query));
  const cached = readSearchCache(query, offset);
  if (cached) {
    const validCached = cached.filter(track => queryMatchesTrack(query, track));
    let acquiredAt = Date.now();
    try { acquiredAt = JSON.parse(localStorage.getItem(searchCacheKey(query, offset))).savedAt; } catch {}
    addToCandidatePool(query, validCached, { fromCache: true, acquiredAt });
    return validCached;
  }

  if (newSearchesThisGeneration >= maxNewSearchesThisGeneration) {
    return [];
  }
  newSearchesThisGeneration++;

  const url = new URL("https://api.spotify.com/v1/search");
  url.search = new URLSearchParams({
    q: query,
    type: "track",
    limit: "10",
    offset: String(offset)
  }).toString();

  for (let attempt = 0; attempt <= MAX_RATE_LIMIT_RETRIES; attempt++) {
    await waitForSearchSlot();

    const response = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` }
    });

    const data = await parseJsonSafely(response);

    if (response.ok) {
      const items = (data?.tracks?.items || []).filter(track => queryMatchesTrack(query, track));
      writeSearchCache(query, offset, items);
      addToCandidatePool(query, items);
      return items;
    }

    if (response.status === 429) {
      const reason = data?.error?.reason;
      if (reason === "QUOTA_EXCEEDED") {
        throw new Error(
          "Spotify: wyczerpano quota aplikacji w Development Mode. To nie jest chwilowy limit szybkości. Odczekaj do odnowienia limitu i spróbuj ponownie później."
        );
      }

      const retryAfterHeader = Number(response.headers.get("Retry-After"));
      const retrySeconds = Number.isFinite(retryAfterHeader) && retryAfterHeader > 0
        ? retryAfterHeader
        : Math.min(30, 2 ** attempt * 2);

      if (attempt >= MAX_RATE_LIMIT_RETRIES) {
        throw new Error(
          `Spotify nadal ogranicza liczbę zapytań (429). Ostatnie Retry-After: ${retrySeconds} s.`
        );
      }

      progressBox.textContent =
        `Spotify zwolniło zapytania. Czekam ${retrySeconds} s i próbuję ponownie...`;
      await sleep(retrySeconds * 1000 + 250);
      continue;
    }

    console.error(data);
    const message = data?.error?.message ? `: ${data.error.message}` : "";
    throw new Error(`Błąd wyszukiwania Spotify: ${response.status}${message}`);
  }

  return [];
}

functions.refreshAccessToken:
async function refreshAccessToken() {
  const refreshToken = localStorage.getItem("spotify_refresh_token");
  if (!refreshToken) return null;

  const response = await fetch("https://accounts.spotify.com/api/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: refreshToken,
      client_id: clientId
    })
  });

  const data = await response.json();
  if (!response.ok) {
    console.error(data);
    clearTokens();
    return null;
  }

  saveTokens(data);
  return data.access_token;
}

