async function cloudApiRequest(token, options = {}) {
  const response = await fetch(CLOUD_STATE_ENDPOINT, {
    ...options,
    headers: {
      ...(options.headers || {}),
      Authorization: `Bearer ${token}`,
      ...(options.body ? { "Content-Type": "application/json" } : {})
    }
  });
  const data = await parseJsonSafely(response);
  if (!response.ok) {
    const error = new Error(data?.error || `Cloudflare D1 HTTP ${response.status}`);
    error.status = response.status;
    throw error;
  }
  return data;
}

functions.syncSpotifyRecentHistory:
async function syncSpotifyRecentHistory(token) {
  const lastSync = Number(localStorage.getItem(RECENT_HISTORY_SYNC_KEY) || 0);
  if (Date.now() - lastSync < RECENT_HISTORY_SYNC_TTL_MS) {
    return 0;
  }

  const response = await fetch(
    "https://api.spotify.com/v1/me/player/recently-played?limit=50",
    { headers: { Authorization: `Bearer ${token}` } }
  );

  if (!response.ok) {
    console.warn(`Nie udało się pobrać historii Spotify: ${response.status}`);
    return 0;
  }

  const data = await response.json();
  const entries = (data.items || [])
    .filter(item => item?.track?.id && item?.played_at)
    .map(item => ({
      trackId: item.track.id,
      trackName: item.track.name || "",
      artistIds: (item.track.artists || []).map(artist => artist.id).filter(Boolean),
      artistNames: (item.track.artists || []).map(artist => artist.name).filter(Boolean),
      trackSignature: trackSignature(item.track),
      playedAt: item.played_at,
      source: "spotify"
    }));

  if (entries.length) mergeHistoryEntries(entries);
  safeSetSmallStorageItem(
    RECENT_HISTORY_SYNC_KEY,
    String(Date.now()),
    "znacznika synchronizacji historii Spotify"
  );
  return entries.length;
}

functions.cleanupOldOfficePlaylists:
async function cleanupOldOfficePlaylists(token) {
  try {
    const profile = await getProfile(token);
    const profileIds = new Set([profile?.id, profile?.account_id].filter(Boolean));
    const oldUris = [];
    let unparseable = 0;
    let offset = 0;

    while (offset < 500) {
      const response = await fetch(
        `https://api.spotify.com/v1/me/playlists?limit=50&offset=${offset}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      const data = await parseJsonSafely(response);
      if (!response.ok) return { found: 0, removed: 0, remaining: 0, unparseable, skipped: `lista playlist: ${response.status}` };

      const items = data?.items || [];
      for (const playlist of items) {
        if (!playlist?.name?.startsWith(OFFICE_PLAYLIST_MATCH_PREFIX) || !playlist?.uri) continue;
        const ownerIds = new Set([playlist?.owner?.id, playlist?.owner?.account_id].filter(Boolean));
        if (profileIds.size && ownerIds.size && ![...ownerIds].some(id => profileIds.has(id))) continue;
        if (profileIds.size && !ownerIds.size) continue;

        const createdAt = officePlaylistCreatedAtFromName(playlist.name);
        if (!createdAt || Number.isNaN(createdAt.getTime())) {
          unparseable++;
          continue;
        }
        if (Date.now() - createdAt.getTime() > OFFICE_PLAYLIST_RETENTION_MS) oldUris.push(playlist.uri);
      }

      if (!data?.next || !items.length) break;
      offset += items.length;
    }

    const uniqueOldUris = [...new Set(oldUris)];
    let accepted = 0;
    for (let i = 0; i < uniqueOldUris.length; i += 40) {
      const batch = uniqueOldUris.slice(i, i + 40);
      const response = await fetch(
        `https://api.spotify.com/v1/me/library?uris=${encodeURIComponent(batch.join(","))}`,
        { method: "DELETE", headers: { Authorization: `Bearer ${token}` } }
      );
      if (response.status === 403) {
        return { found: uniqueOldUris.length, removed: accepted, remaining: uniqueOldUris.length - accepted, unparseable, skipped: "brak scope user-library-modify; wyloguj i połącz Spotify ponownie" };
      }
      if (!response.ok) return { found: uniqueOldUris.length, removed: accepted, remaining: uniqueOldUris.length - accepted, unparseable, skipped: `usuwanie z biblioteki: ${response.status}` };
      accepted += batch.length;
    }

    // Kontrola po operacji na tym samym źródle, z którego czytamy boczną bibliotekę.
    // Nie zakładamy już, że sam status 2xx oznacza, że użytkownik faktycznie przestał
    // widzieć playlistę.
    const target = new Set(uniqueOldUris);
    const stillVisible = new Set();
    if (target.size) {
      await sleep(350);
      let verifyOffset = 0;
      while (verifyOffset < 500) {
        const response = await fetch(
          `https://api.spotify.com/v1/me/playlists?limit=50&offset=${verifyOffset}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const data = await parseJsonSafely(response);
        if (!response.ok) break;
        const items = data?.items || [];
        for (const playlist of items) if (target.has(playlist?.uri)) stillVisible.add(playlist.uri);
        if (!data?.next || !items.length) break;
        verifyOffset += items.length;
      }
    }

    return {
      found: uniqueOldUris.length,
      removed: Math.max(0, uniqueOldUris.length - stillVisible.size),
      remaining: stillVisible.size,
      unparseable,
      skipped: ""
    };
  } catch (err) {
    console.warn("Nie udało się posprzątać starych playlist Office Music Mixer:", err);
    return { found: 0, removed: 0, remaining: 0, unparseable: 0, skipped: err.message || "nieznany błąd" };
  }
}

functions.createPlaylist:
async function createPlaylist(token, selected, total) {
  const names = selected.map(p => p.name).join(", ");
  const stamp = officePlaylistTimestamp();

  const response = await fetch("https://api.spotify.com/v1/me/playlists", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      name: `${OFFICE_PLAYLIST_PREFIX}${stamp}`,
      public: false,
      description: names
    })
  });

  const data = await response.json();
  if (!response.ok) {
    console.error(data);
    throw new Error(`Nie udało się utworzyć playlisty: ${response.status}`);
  }

  return data;
}

functions.addItemsToPlaylist:
async function addItemsToPlaylist(token, playlistId, uris) {
  // Spotify przyjmuje maksymalnie 100 pozycji w jednym żądaniu.
  // v25 obsługuje długie, całodzienne playlisty przez porcjowanie.
  let lastData = null;
  for (let i = 0; i < uris.length; i += 100) {
    const chunk = uris.slice(i, i + 100);
    const response = await fetch(
      `https://api.spotify.com/v1/playlists/${playlistId}/items`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ uris: chunk })
      }
    );

    const data = await response.json();
    if (!response.ok) {
      console.error(data);
      throw new Error(`Nie udało się dodać utworów: ${response.status}`);
    }
    lastData = data;
  }

  return lastData;
}

functions.lastFmRequest:
async function lastFmRequest(method, params = {}, ttlMs = LASTFM_CACHE_TTL_MS) {
  const cached = readLastFmCache(method, params, ttlMs);
  if (cached) {
    try { Object.defineProperty(cached, "ommAcquiredAt", { value: JSON.parse(localStorage.getItem(lastFmCacheKey(method, params))).savedAt }); } catch {}
    return cached;
  }

  const url = new URL(lastFmApiRoot);
  url.search = new URLSearchParams({
    method,
    api_key: lastFmApiKey,
    format: "json",
    ...Object.fromEntries(Object.entries(params).map(([k, v]) => [k, String(v)]))
  }).toString();

  const response = await fetch(url);
  const data = await parseJsonSafely(response);
  if (!response.ok || data?.error) {
    const msg = data?.message || `HTTP ${response.status}`;
    throw new Error(`błąd API ${msg}`);
  }

  writeLastFmCache(method, params, data);
  return data;
}

functions.init:
async function init() {
  const params = new URLSearchParams(window.location.search);
  const code = params.get("code");
  const returnedState = params.get("state");
  const error = params.get("error");

  if (error) {
    statusBox.innerHTML =
      `<span class="error">Spotify zwrócił błąd: ${error}</span>`;
    return;
  }

  if (code) {
    const expectedState = sessionStorage.getItem("spotify_auth_state");

    if (!expectedState || returnedState !== expectedState) {
      clearTokens();
      statusBox.innerHTML =
        '<span class="error">Błąd weryfikacji logowania.</span>';
      return;
    }

    try {
      statusBox.textContent = "Kończę logowanie...";
      const token = await exchangeCodeForToken(code);
      sessionStorage.removeItem("spotify_auth_state");

      window.history.replaceState({}, document.title, redirectUri);
      await showLoggedIn(token);
      return;
    } catch (err) {
      console.error(err);
      statusBox.innerHTML = `<span class="error">${err.message}</span>`;
      return;
    }
  }

  try {
    const token = await getValidAccessToken();

    if (token) {
      await showLoggedIn(token);
    } else {
      statusBox.textContent = "Niepołączony";
    }
  } catch (err) {
    console.error(err);
    clearTokens();
    statusBox.innerHTML =
      '<span class="error">Sesja Spotify wygasła. Zaloguj się ponownie.</span>';
  }
}
